// src/scanners/base.ts
function coerceScanInput(value) {
  return typeof value === "string" ? value : "";
}
function allowResult(scanner, input) {
  return {
    sanitized: input,
    valid: true,
    score: 0,
    decision: "ALLOW",
    reasons: [],
    matches: [],
    scanner
  };
}
function blockResult(scanner, input, score, reasons, matches, blockAt = 0.8, hitlAt = 0.5) {
  const decision = score >= blockAt ? "BLOCK" : score >= hitlAt ? "HITL" : "ALLOW";
  return {
    sanitized: input,
    valid: decision === "ALLOW",
    score,
    decision,
    reasons,
    matches: matches ?? [],
    scanner
  };
}

