// src/scanners/prompt-injection.ts
var SEVERITY_WEIGHTS = {
  critical: 1,
  high: 0.75,
  medium: 0.5,
  low: 0.25
};
var STRICTNESS_NORMALIZER = {
  strict: 1,
  moderate: 1.5,
  lenient: 2.5
};
var PromptInjectionScanner = class {
  constructor(options = {}) {
    /** @inheritdoc */
    this.name = "prompt-injection";
    this.strictness = options.strictness ?? "moderate";
    this.blockAt = options.blockAt ?? 0.8;
    this.hitlAt = options.hitlAt ?? 0.5;
    const allPatterns = [
      ...INJECTION_PATTERNS,
      ...options.customPatterns ?? []
    ];
    this.compiledPatterns = allPatterns.map((def) => ({
      def,
      re: new RegExp(
        def.pattern.source,
        def.pattern.flags.includes("g") ? def.pattern.flags : def.pattern.flags + "g"
      )
    }));
  }
  /** @inheritdoc */
  scan(input, ctx) {
    input = coerceScanInput(input);
    const effectiveStrictness = ctx?.strictness ?? this.strictness;
    const normalizer = STRICTNESS_NORMALIZER[effectiveStrictness] ?? STRICTNESS_NORMALIZER.moderate;
    const matchDetails = [];
    const matchedCategories = /* @__PURE__ */ new Set();
    let rawScore = 0;
    for (const { def, re } of this.compiledPatterns) {
      re.lastIndex = 0;
      let m;
      while ((m = re.exec(input)) !== null) {
        const weight = SEVERITY_WEIGHTS[def.severity] ?? 0.5;
        rawScore += weight;
        matchedCategories.add(def.category);
        matchDetails.push({
          pattern: def.id,
          startIndex: m.index,
          endIndex: m.index + m[0].length,
          category: def.category
        });
        if (m[0].length === 0) break;
      }
    }
    if (matchDetails.length === 0) {
      return allowResult(this.name, input);
    }
    const score = Math.min(1, rawScore / normalizer);
    const reasons = Array.from(matchedCategories);
    return blockResult(
      this.name,
      input,
      score,
      reasons,
      matchDetails,
      this.blockAt,
      this.hitlAt
    );
  }
};
var defaultPromptInjectionScanner = new PromptInjectionScanner();
function checkPromptInjection(input, options) {
  const scanner = options ? new PromptInjectionScanner(options) : defaultPromptInjectionScanner;
  return scanner.scan(input);
}

